import { HTTPController, HTTPMethod, HTTPMethodEnum, HTTPParam, HTTPBody, Inject } from 'egg';
import { UserService } from './UserService.ts';

@HTTPController({ path: '/api/users' })
export class UserController {
  @Inject()
  userService: UserService;

  @HTTPMethod({ method: HTTPMethodEnum.GET, path: '/:id' })
  async show(@HTTPParam() id: string) {
    return await this.userService.getById(id);
  }

  @HTTPMethod({ method: HTTPMethodEnum.POST, path: '/' })
  async create(@HTTPBody() body: { name: string; email: string }) {
    return await this.userService.create(body);
  }
}

import { app } from '@eggjs/mock/bootstrap';

describe('UserController', () => {
  it('should create user', () => {
    return app.httpRequest()
      .post('/api/users')
      .send({ name: 'test', email: 'test@example.com' })
      .expect(200);
  });
});

