import { SingletonProto, Inject } from 'egg';
import { PaymentService } from '../payment/PaymentService.ts';

@SingletonProto()
export class OrderService {
  @Inject()
  paymentService: PaymentService;

  async create(data: { productId: string; amount: number }) {
    const tx = await this.paymentService.charge(data.amount);
    return { orderId: 'order-1', transactionId: tx.id };
  }
}

import { ContextProto } from 'egg';

@ContextProto()
export class CartService {
  async addItem(productId: string) {
    return { productId, quantity: 1 };
  }
}

import { app } from '@eggjs/mock/bootstrap';
import assert from 'node:assert';
import { CartService } from '../app/modules/cart/CartService.ts';

describe('CartService', () => {
  it('should add item', async () => {
    const cartService = await app.getEggObject(CartService);
    const item = await cartService.addItem('p1');
    assert.equal(item.productId, 'p1');
  });
});

